[call] {"name":"Write","arguments":{"file_path":"briefkit.ps1","content":"Set-StrictMode -Version Latest\n\nfunction Build-ShiftBrief {\n    param(\n        [Parameter(Mandatory = $true)]\n        [string]$Path\n    )\n\n    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {\n        throw \"briefkit: log not found: $Path\"\n    }\n\n    # Linear build: StringBuilder, one pass streaming lines from disk.\n    $doc = [System.Text.StringBuilder]::new()\n    $null = $doc.Append(\"shift brief`n\")\n\n    $entries = 0\n    $skipped = 0\n    $levels = [System.Collections.Generic.Dictionary[string, int]]::new()\n\n    foreach ($line in [System.IO.File]::ReadLines($Path)) {\n        # Blank lines (empty or whitespace-only) are ignored, not counted.\n        if ($line.Length -eq 0 -or [string]::IsNullOrWhiteSpace($line)) { continue }\n\n        # Exactly 5 non-empty space-separated fields; a double space yields an\n        # empty field and counts as a collector glitch.\n        $fields = $line.Split(' ')\n        if ($fields.Count -ne 5) {\n            $skipped++\n            continue\n        }\n        $glitch = $false\n        for ($i = 0; $i -lt 5; $i++) {\n            if ($fields[$i].Length -eq 0) { $glitch = $true; break }\n        }\n        if ($glitch) {\n            $skipped++\n            continue\n        }\n\n        $entries++\n        $null = $doc.`\n            Append($entries.ToString('d7')).Append(' ').`\n            Append($fields[2].PadRight(5)).Append(' ').`\n            Append($fields[0]).Append('/').Append($fields[1]).Append(' ').`\n            Append($fields[3]).Append('ms ').`\n            Append($fields[4]).Append(\"`n\")\n\n        # Case-sensitive level counting: a plain @{} merges 'WARN' and 'warn',\n        # so use the generic dictionary with its ordinal default comparer.\n        if ($levels.ContainsKey($fields[2])) {\n            $levels[$fields[2]]++\n        } else {\n            $levels[$fields[2]] = 1\n        }\n    }\n\n    $null